CREATE TABLE messages(
    id         INT PRIMARY KEY IDENTITY, 
    message    VARCHAR(255) NOT NULL, 
    created_at DATETIMEOFFSET NOT NULL
);

INSERT INTO messages(message,created_at)
VALUES('DATETIMEOFFSET demo',
         CAST('2019-02-28 01:45:00.0000000 -08:00' AS DATETIMEOFFSET));

DECLARE @stored DATETIMEOFFSET = '2024-06-01 10:00:00 +02:00';

SELECT
    @stored                                              AS stored_value,
    @stored AT TIME ZONE 'Central Europe Standard Time'  AS berlin,
    @stored AT TIME ZONE 'Eastern Standard Time'         AS new_york,
    @stored AT TIME ZONE 'India Standard Time'           AS mumbai;

SELECT SYSDATETIMEOFFSET() AS server_now_with_offset;
